t.script:
klaviyo = function() {
    console.log("Klaviyo events are not triggered for the website administrator");
}

klaviyo.push(["track", "Viewed Product", {
    "ProductName": "",
    "ProductID": ,
    "SKU": "",
    "Price": ,
    "URL": "",
    "ImageURL": "",
}]);
klaviyo.push(["trackViewedItem", {
    "Title": "",
    "ItemId": ,
    "URL": "",
    "ImageUrl": "",
    "Metadata": {
        "Price": ,
    }
}]);

document.addEventListener('DOMContentLoaded', function() {
    var addToCartBtn = document.getElementById("add_to_cart") || document.querySelector(".js_check_product a.a-submit");
    if (addToCartBtn) {
        addToCartBtn.addEventListener('click', function() {
            var qtyInput = document.querySelector('input[name="add_qty"]');
            var qty = qtyInput ? parseInt(qtyInput.value, 10) : 1;
            klaviyo.push(["track", "Added to Cart", {
                "AddedItemProductName": "",
                "AddedItemProductID": ,
                "AddedItemSKU": "",
                "AddedItemPrice": ,
                "AddedItemQuantity": qty,
                "AddedItemURL": "",
                "AddedItemImageURL": "",
                "ItemNames": [""],
                "Items": [{
                    "ProductID": ,
                    "SKU": "",
                    "ProductName": "",
                    "Quantity": qty,
                    "ItemPrice": ,
                    "RowTotal":  * qty,
                    "ProductURL": "",
                    "ImageURL": ""
                }]
            }]);
        });
    }
});
